// ISC 12 Mathematics ch17 Probability — practice bank with independent re-solve checks. Every key is computed
// with exact fractions (prob.mjs) and cross-checked a second way: by brute-force enumeration of equally likely
// outcomes (dice, coins, tokens, cards, ordered draws), or, for total probability and Bayes' theorem, by counting
// an imagined population of whole items (for example 1000 bolts or 1000 days) built from the stated percentages.
// Distributions are checked to sum to 1 and every mean is recomputed as the average of X over the sample space.
// All contexts, tables and numbers are SOYL's own (D-036); the CBSE 12 ch13 bank was checked so that no set-up,
// figure or wording is reused.
import { Q, mk } from '../../isc-12-mathematics-ch01/src/lib.mjs';
import { fr, sum, prod, P, cond, dice2, die, coins, cards, draws, bag, cart, range } from './prob.mjs';

/** String.raw, except that a backslash-n not followed by a lower-case letter becomes a newline. */
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
/** LaTeX of an exact value, without dollars. */
export const T = (x) => fr(x).tex();
const S = (x) => fr(x).toString();
/** which() on exact fractions. */
const W = (C, vals, target) => C.which(vals.map(S), S(target));

// ---------------------------------------------------------------- shared data (imagined), exported for the decks
/** Survey of 200 Class 12 students at an imagined Dehradun school: stream × chess club. */
export const SURVEY = { sciChess: 45, sciNo: 75, comChess: 35, comNo: 45 };
const students = [
  ...Array.from({ length: SURVEY.sciChess }, () => ({ sci: true, chess: true })),
  ...Array.from({ length: SURVEY.sciNo }, () => ({ sci: true, chess: false })),
  ...Array.from({ length: SURVEY.comChess }, () => ({ sci: false, chess: true })),
  ...Array.from({ length: SURVEY.comNo }, () => ({ sci: false, chess: false })),
];
export const pSurvey = {
  chessGivenSci: cond(students, (s) => s.chess, (s) => s.sci),
  sciGivenChess: cond(students, (s) => s.sci, (s) => s.chess),
  chess: P(students, (s) => s.chess),
  chessGivenCom: cond(students, (s) => s.chess, (s) => !s.sci),
};
/** Partition problems: priors and likelihoods, and an equivalent whole-number population for cross-checks. */
export const BOLTS = { names: ['P', 'Q', 'R'], pri: [fr(1, 2), fr(3, 10), fr(1, 5)], lik: [fr(1, 50), fr(3, 100), fr(1, 20)] };
export const BUS = { names: ['Route X', 'Route Y', 'Route Z'], pri: [fr(1, 2), fr(1, 3), fr(1, 6)], lik: [fr(1, 10), fr(1, 5), fr(1, 4)] };
export const RAIN = { pri: [fr(3, 10), fr(7, 10)], lik: [fr(4, 5), fr(1, 10)] }; // rain / dry; P(forecast says rain | …)
export const TEST = { pri: [fr(1, 50), fr(49, 50)], lik: [fr(9, 10), fr(1, 20)] }; // ill / well; P(positive | …)
export const QUIZ = { pri: [fr(3, 5), fr(2, 5)], lik: [fr(1), fr(1, 5)] }; // knows / guesses (5 options); P(correct | …)
export const CRATES = { pri: [fr(1, 2), fr(1, 2)], lik: [fr(8, 12), fr(5, 12)] }; // ripe mango from crate I / II
export const total = (D) => sum(...D.pri.map((p, i) => p.mul(D.lik[i])));
export const bayes = (D, i) => D.pri[i].mul(D.lik[i]).div(total(D));
/** Population of N items split by the priors, each group marked by the likelihood: [{ g, a }]. */
function population(D, N) {
  const out = [];
  D.pri.forEach((p, i) => {
    const n = p.mul(N), k = n.mul(D.lik[i]);
    if (n.d !== 1 || k.d !== 1) throw new Error(`population ${N} not whole for group ${i}`);
    for (let j = 0; j < n.n; j++) out.push({ g: i, a: j < k.n });
  });
  return out;
}
/** Total probability and every posterior agree with direct counting in a population of N. */
export function popCheck(D, N) {
  const pop = population(D, N);
  const ok = P(pop, (x) => x.a).eq(total(D)) && D.pri.every((_, i) => cond(pop, (x) => x.g === i, (x) => x.a).eq(bayes(D, i)));
  return ok && sum(...D.pri.map((_, i) => bayes(D, i))).eq(1);
}
/** Distribution of X over equally likely outcomes: sorted [[x, P(X = x)], …], with its mean checked by averaging. */
export function dist(space, X) {
  const m = new Map();
  for (const w of space) m.set(X(w), (m.get(X(w)) ?? 0) + 1);
  const rows = [...m.entries()].sort((a, b) => a[0] - b[0]).map(([x, c]) => [x, fr(c, space.length)]);
  if (!sum(...rows.map(([, p]) => p)).eq(1)) throw new Error('distribution does not sum to 1');
  const mean = sum(...rows.map(([x, p]) => p.mul(x)));
  if (!mean.eq(fr(space.reduce((s, w) => s + X(w), 0), space.length))) throw new Error('mean mismatch');
  return { rows, mean, p: (x) => rows.find(([v]) => v === x)?.[1] ?? fr(0) };
}
export const pairsOf = (items) => { const out = []; for (let i = 0; i < items.length; i++) for (let j = i + 1; j < items.length; j++) out.push([items[i], items[j]]); return out; };
/** Two bulbs from 6, of which 2 are fused; X = number of fused bulbs. */
export const BULBS = dist(pairsOf(bag({ F: 2, G: 4 })), (w) => w.filter((x) => x === 'F').length);
/** Two dice; X = absolute difference of the numbers. */
export const DIFF = dist(dice2, (w) => Math.abs(w[0] - w[1]));
/** Committee of 2 from 3 girls and 2 boys; X = number of girls. */
export const GIRLS = dist(pairsOf(bag({ G: 3, B: 2 })), (w) => w.filter((x) => x === 'G').length);
/** A coin is tossed until a head appears, at most three times; X = number of tosses (from the 8 outcomes of 3 tosses). */
export const TOSSES = dist(coins(3), (w) => (w[0] === 'H' ? 1 : w[1] === 'H' ? 2 : 3));
/** P(X = x) = k(x² + 1), x = 0, 1, 2, 3. */
export const KDIST = (() => { const xs = [0, 1, 2, 3]; const k = fr(1, xs.reduce((s, x) => s + x * x + 1, 0)); const rows = xs.map((x) => [x, k.mul(x * x + 1)]); return { k, rows, mean: sum(...rows.map(([x, p]) => p.mul(x))) }; })();
if (!sum(...KDIST.rows.map(([, p]) => p)).eq(1)) throw new Error('KDIST');
/** Box of 10 tea packets, 3 of them Darjeeling, drawn without replacement. */
const TEA = bag({ D: 3, A: 7 });

// =============================================================== MCQ (24)
Q('m01', mk.mcq({ stem: r`For two events of a school sports draw, $P(B) = \dfrac{3}{8}$ and $P(A \cap B) = \dfrac{3}{20}$. The conditional probability $P(A \mid B)$ is`, opts: [`$${T('2/5')}$`, `$${T('9/160')}$`, `$${T('3/8')}$`, `$${T('5/2')}$`], key: 'a', sol: r`$P(A \mid B) = \dfrac{P(A \cap B)}{P(B)} = \dfrac{3}{20} \div \dfrac{3}{8} = \dfrac{2}{5}$. Option (b) multiplies instead of dividing; option (d) divides the wrong way round and exceeds $1$.`, d: 1, c: 'understanding', t: [1], time: 45 }),
  (C) => W(C, ['2/5', '9/160', '3/8', '5/2'], fr(3, 20).div(fr(3, 8))));
Q('m02', mk.mcq({ stem: r`In the Dehradun survey of $200$ Class 12 students, $120$ study science and $45$ of those belong to the chess club. A science student is picked at random. The probability that the student belongs to the chess club is`, opts: [`$${T('3/8')}$`, `$${T('9/40')}$`, `$${T('9/16')}$`, `$${T('2/5')}$`], key: 'a', sol: r`Restrict attention to the $120$ science students: $\dfrac{45}{120} = \dfrac{3}{8}$. Option (b) is $\dfrac{45}{200}$, the joint probability; option (c) is the reverse conditional $P(\text{science} \mid \text{chess})$.`, d: 2, c: 'understanding', t: [1] }),
  (C) => W(C, ['3/8', '9/40', '9/16', '2/5'], pSurvey.chessGivenSci));
Q('m03', mk.mcq({ stem: r`Two dice are thrown at a board-game evening. Given that at least one die shows $4$, the probability that the two numbers add up to $7$ is`, opts: [`$${T('2/11')}$`, `$${T('1/6')}$`, `$${T('1/18')}$`, `$${T('2/9')}$`], key: 'a', sol: r`At least one $4$: $11$ equally likely outcomes. Of these, $(3, 4)$ and $(4, 3)$ add to $7$, so the probability is $\dfrac{2}{11}$. Option (b) ignores the condition; option (c) is the joint probability $\dfrac{2}{36}$.`, d: 2, c: 'application', t: [1] }),
  (C) => W(C, ['2/11', '1/6', '1/18', '2/9'], cond(dice2, (w) => w[0] + w[1] === 7, (w) => w[0] === 4 || w[1] === 4)));
Q('m04', mk.mcq({ stem: r`Raffle tokens numbered $1$ to $15$ are mixed in a tin at a Nashik school fair, and one is drawn. If the number drawn is even, the probability that it is also a multiple of $3$ is`, opts: [`$${T('2/7')}$`, `$${T('1/3')}$`, `$${T('2/15')}$`, `$${T('1/5')}$`], key: 'a', sol: r`Even numbers: $2, 4, \ldots, 14$, seven of them. Multiples of $3$ among them: $6$ and $12$. So the probability is $\dfrac{2}{7}$. Option (c) uses all $15$ tokens.`, d: 2, c: 'understanding', t: [1] }),
  (C) => { const sp = range(1, 15).map((x) => [x]); W(C, ['2/7', '1/3', '2/15', '1/5'], cond(sp, (w) => w[0] % 3 === 0, (w) => w[0] % 2 === 0)); });
Q('m05', mk.mcq({ stem: r`A card is drawn from a well-shuffled pack of $52$ for a card trick. Given that the card is red, the probability that it is a jack, queen or king is`, opts: [`$${T('3/13')}$`, `$${T('3/26')}$`, `$${T('6/13')}$`, `$${T('1/13')}$`], key: 'a', sol: r`There are $26$ red cards and $6$ of them are jacks, queens or kings: $\dfrac{6}{26} = \dfrac{3}{13}$. Option (b) is the joint probability $\dfrac{6}{52}$.`, d: 1, c: 'understanding', t: [1], time: 45 }),
  (C) => W(C, ['3/13', '3/26', '6/13', '1/13'], cond(cards, (c) => c.rank >= 11, (c) => c.red)));
Q('m06', mk.mcq({ stem: r`For events $A$ and $B$ of a weather study, $P(A) = 0.6$, $P(B) = 0.5$ and $P(A \cup B) = 0.8$. The value of $P(A \mid B)$ is`, opts: [`$${T('3/5')}$`, `$${T('1/2')}$`, `$${T('3/10')}$`, `$${T('4/5')}$`], key: 'a', sol: r`$P(A \cap B) = 0.6 + 0.5 - 0.8 = 0.3$, so $P(A \mid B) = \dfrac{0.3}{0.5} = \dfrac{3}{5}$. Option (b) is $P(B \mid A)$ and option (c) is $P(A \cap B)$.`, d: 2, c: 'understanding', t: [1] }),
  (C) => { const AB = fr(3, 5).add(fr(1, 2)).sub(fr(4, 5)); C.assert(AB.div(fr(3, 5)).eq(fr(1, 2)), 'P(B|A) = 1/2 is a distractor'); W(C, ['3/5', '1/2', '3/10', '4/5'], AB.div(fr(1, 2))); });
Q('m07', mk.mcq({ stem: r`According to the addition theorem, for any two events $A$ and $B$ of the same sample space, $P(A \cup B)$ equals`, opts: [r`$P(A) + P(B) - P(A \cap B)$`, r`$P(A) + P(B)$`, r`$P(A)\,P(B)$`, r`$P(A) + P(B) + P(A \cap B)$`], key: 'a', sol: r`Adding $P(A)$ and $P(B)$ counts the overlap twice, so it is subtracted once. Option (b) holds only for mutually exclusive events, and option (c) is the product rule for independent events.`, d: 1, c: 'recall', t: [1], time: 40 }),
  (C) => { const A = (w) => w[0] % 2 === 0, B = (w) => w[0] >= 4; C.assert(P(die, (w) => A(w) || B(w)).eq(P(die, A).add(P(die, B)).sub(P(die, (w) => A(w) && B(w)))), 'addition theorem on a die'); C.key('a'); });
Q('m08', mk.mcq({ stem: r`At a tea-tasting session in Siliguri, two packets are taken one after another, without replacement, from a box of $10$ packets of which $3$ are Darjeeling. The probability that both are Darjeeling is`, opts: [`$${T('1/15')}$`, `$${T('9/100')}$`, `$${T('3/10')}$`, `$${T('7/15')}$`], key: 'a', sol: r`By the multiplication theorem, $\dfrac{3}{10} \times \dfrac{2}{9} = \dfrac{1}{15}$. Option (b) treats the draws as with replacement; option (d) is the probability that neither is Darjeeling.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { const sp = draws(TEA, 2); C.assert(P(sp, (w) => w[0] === 'A' && w[1] === 'A').eq(fr(7, 15)), 'neither 7/15'); W(C, ['1/15', '9/100', '3/10', '7/15'], P(sp, (w) => w[0] === 'D' && w[1] === 'D')); });
Q('m09', mk.mcq({ stem: r`From the same box of $10$ tea packets ($3$ Darjeeling), three packets are taken one at a time without replacement. The probability that the first Darjeeling packet appears on the third draw is`, opts: [`$${T('7/40')}$`, `$${T('3/10')}$`, `$${T('147/1000')}$`, `$${T('7/24')}$`], key: 'a', sol: r`The first two must be non-Darjeeling and the third Darjeeling: $\dfrac{7}{10} \times \dfrac{6}{9} \times \dfrac{3}{8} = \dfrac{7}{40}$. Option (c) uses replacement ($0.7 \times 0.7 \times 0.3$).`, d: 3, c: 'application', t: [2] }),
  (C) => W(C, ['7/40', '3/10', '147/1000', '7/24'], P(draws(TEA, 3), (w) => w[0] === 'A' && w[1] === 'A' && w[2] === 'D')));
Q('m10', mk.mcq({ stem: r`At a Lucknow badminton camp, Ayesha and Kabir serve independently; Ayesha's serve is good with probability $\dfrac{4}{5}$ and Kabir's with probability $\dfrac{2}{3}$. The probability that exactly one of the two serves is good is`, opts: [`$${T('2/5')}$`, `$${T('8/15')}$`, `$${T('1/15')}$`, `$${T('14/15')}$`], key: 'a', sol: r`Exactly one: $\dfrac{4}{5} \cdot \dfrac{1}{3} + \dfrac{1}{5} \cdot \dfrac{2}{3} = \dfrac{4}{15} + \dfrac{2}{15} = \dfrac{2}{5}$. Option (b) is both good; option (d) is at least one good.`, d: 3, c: 'application', t: [2] }),
  (C) => { const a = fr(4, 5), b = fr(2, 3); C.assert(fr(1).sub(a.comp().mul(b.comp())).eq(fr(14, 15)), 'at least one 14/15'); W(C, ['2/5', '8/15', '1/15', '14/15'], a.mul(b.comp()).add(a.comp().mul(b))); });
Q('m11', mk.mcq({ stem: r`A clinic's back-up system has three independent servers, each failing on a given day with probability $\dfrac{1}{5}$. The probability that at least one server is running that day is`, opts: [`$${T('124/125')}$`, `$${T('64/125')}$`, `$${T('1/125')}$`, `$${T('3/5')}$`], key: 'a', sol: r`All three fail with probability $\left(\dfrac{1}{5}\right)^3 = \dfrac{1}{125}$, so at least one runs with probability $1 - \dfrac{1}{125} = \dfrac{124}{125}$. Option (b) is the chance that all three run.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { const sp = cart(range(1, 5), range(1, 5), range(1, 5)); W(C, ['124/125', '64/125', '1/125', '3/5'], P(sp, (w) => w.some((x) => x > 1))); });
Q('m12', mk.mcq({ stem: r`Two dice are rolled for a ludo move. Let $A$ be "the first die shows an even number". With which of these events is $A$ independent?`, opts: ['the sum of the two numbers is 7', 'the sum of the two numbers is 8', 'both dice show even numbers', 'the first die shows 2'], key: 'a', sol: r`$P(A) = \dfrac{1}{2}$ and $P(\text{sum } 7) = \dfrac{1}{6}$; the outcomes $(2, 5), (4, 3), (6, 1)$ give $P(A \cap \text{sum } 7) = \dfrac{3}{36} = \dfrac{1}{12} = \dfrac{1}{2} \cdot \dfrac{1}{6}$. For sum $8$, $P = \dfrac{3}{36} \ne \dfrac{1}{2} \cdot \dfrac{5}{36}$; the other two options are contained in $A$.`, d: 3, c: 'analysis', t: [2] }),
  (C) => { const A = (w) => w[0] % 2 === 0; const ind = (B) => P(dice2, (w) => A(w) && B(w)).eq(P(dice2, A).mul(P(dice2, B))); C.which([ind((w) => w[0] + w[1] === 7), ind((w) => w[0] + w[1] === 8), ind((w) => w[0] % 2 === 0 && w[1] % 2 === 0), ind((w) => w[0] === 2)].map(String), 'true'); });
Q('m13', mk.mcq({ stem: r`In the Dehradun survey ($200$ students; $80$ in the chess club; $120$ in science, of whom $45$ play chess), are "science student" and "chess club member" independent?`, opts: [r`No, because $P(\text{chess} \mid \text{science}) = \dfrac{3}{8}$ but $P(\text{chess}) = \dfrac{2}{5}$`, r`Yes, because both events have non-zero probability`, r`Yes, because $P(\text{chess} \mid \text{science}) = P(\text{chess})$`, r`No, because the events are mutually exclusive`], key: 'a', sol: r`$P(\text{chess}) = \dfrac{80}{200} = \dfrac{2}{5}$ while $P(\text{chess} \mid \text{science}) = \dfrac{45}{120} = \dfrac{3}{8}$. Knowing the stream changes the probability, so the events are dependent. They are not mutually exclusive: $45$ students are in both.`, d: 3, c: 'analysis', t: [2] }),
  (C) => { C.assert(!pSurvey.chessGivenSci.eq(pSurvey.chess) && pSurvey.chess.eq(fr(2, 5)) && pSurvey.chessGivenSci.eq(fr(3, 8)), 'dependent'); C.key('a'); });
Q('m14', mk.mcq({ stem: r`Events $A$ and $B$ of a quality check are independent, with $P(A) = \dfrac{2}{5}$ and $P(A \cup B) = \dfrac{7}{10}$. Then $P(B)$ is`, opts: [`$${T('1/2')}$`, `$${T('3/10')}$`, `$${T('7/25')}$`, `$${T('3/5')}$`], key: 'a', sol: r`$P(A \cup B) = P(A) + P(B) - P(A)P(B)$, so $\dfrac{7}{10} = \dfrac{2}{5} + \dfrac{3}{5}P(B)$, giving $P(B) = \dfrac{3}{10} \div \dfrac{3}{5} = \dfrac{1}{2}$. Option (b) forgets the overlap term.`, d: 3, c: 'application', t: [2] }),
  (C) => { const a = fr(2, 5), u = fr(7, 10); const b = u.sub(a).div(a.comp()); C.assert(a.add(b).sub(a.mul(b)).eq(u), 'back-substitution'); W(C, ['1/2', '3/10', '7/25', '3/5'], b); });
Q('m15', mk.mcq({ stem: r`An imagined Ludhiana factory makes bolts on machines P, Q and R, which produce $50\%$, $30\%$ and $20\%$ of the output and spoil $2\%$, $3\%$ and $5\%$ of what they make. The probability that a bolt picked at random from the day's output is defective is`, opts: [`$${T('29/1000')}$`, `$${T('1/10')}$`, `$${T('1/30')}$`, `$${T('3/100')}$`], key: 'a', sol: r`Total probability: $0.5 \times 0.02 + 0.3 \times 0.03 + 0.2 \times 0.05 = 0.01 + 0.009 + 0.01 = 0.029$. Option (b) adds the defect rates; option (c) averages them without weights.`, d: 2, c: 'understanding', t: [3] }),
  (C) => { C.assert(popCheck(BOLTS, 1000), '1000 bolts'); W(C, ['29/1000', '1/10', '1/30', '3/100'], total(BOLTS)); });
Q('m16', mk.mcq({ stem: r`A Pune commuter takes route X, Y or Z with probabilities $\dfrac{1}{2}$, $\dfrac{1}{3}$ and $\dfrac{1}{6}$, and is late with probabilities $\dfrac{1}{10}$, $\dfrac{1}{5}$ and $\dfrac{1}{4}$ on these routes. The probability that she is late on a given day is`, opts: [`$${T('19/120')}$`, `$${T('11/20')}$`, `$${T('11/60')}$`, `$${T('1/6')}$`], key: 'a', sol: r`$\dfrac{1}{2} \cdot \dfrac{1}{10} + \dfrac{1}{3} \cdot \dfrac{1}{5} + \dfrac{1}{6} \cdot \dfrac{1}{4} = \dfrac{6}{120} + \dfrac{8}{120} + \dfrac{5}{120} = \dfrac{19}{120}$. Option (b) adds the lateness probabilities without weights.`, d: 2, c: 'understanding', t: [3] }),
  (C) => { C.assert(popCheck(BUS, 120), '120 days'); W(C, ['19/120', '11/20', '11/60', '1/6'], total(BUS)); });
Q('m17', mk.mcq({ stem: r`The theorem of total probability for an event $A$ uses events $E_1, E_2, \ldots, E_n$. Which condition must these events satisfy?`, opts: ['They must be pairwise disjoint, have non-zero probabilities and together fill the sample space', 'They must be independent of A', 'They must all have equal probabilities', 'They must all be contained in A'], key: 'a', sol: r`The $E_i$ must form a **partition**: no two overlap, each has $P(E_i) > 0$, and their union is the whole sample space. They need not be equally likely or independent of $A$.`, d: 1, c: 'recall', t: [3], time: 40 }),
  (C) => { const parts = [(w) => w[0] <= 2, (w) => w[0] === 3, (w) => w[0] >= 4]; C.assert(die.every((w) => parts.filter((p) => p(w)).length === 1), 'a partition of a die'); C.key('a'); });
Q('m18', mk.mcq({ stem: r`At a Ratnagiri packhouse a coin decides which of two crates a mango is taken from. Crate I holds $8$ ripe and $4$ raw mangoes; crate II holds $5$ ripe and $7$ raw. The probability that the mango taken is ripe is`, opts: [`$${T('13/24')}$`, `$${T('13/12')}$`, `$${T('2/3')}$`, `$${T('5/12')}$`], key: 'a', sol: r`$\dfrac{1}{2} \cdot \dfrac{8}{12} + \dfrac{1}{2} \cdot \dfrac{5}{12} = \dfrac{13}{24}$. Option (b) forgets the factor $\dfrac{1}{2}$ and exceeds $1$.`, d: 2, c: 'understanding', t: [3] }),
  (C) => { const sp = cart(['I', 'II'], range(0, 11)); C.assert(P(sp, ([c, i]) => (c === 'I' ? i < 8 : i < 5)).eq(total(CRATES)), 'enumeration'); W(C, ['13/24', '13/12', '2/3', '5/12'], total(CRATES)); });
Q('m19', mk.mcq({ stem: r`In the Ludhiana bolt factory (machines P, Q, R make $50\%$, $30\%$, $20\%$; defect rates $2\%$, $3\%$, $5\%$), a bolt is found to be defective. The probability that machine R made it is`, opts: [`$${T('10/29')}$`, `$${T('1/5')}$`, `$${T('1/20')}$`, `$${T('9/29')}$`], key: 'a', sol: r`By Bayes' theorem, $P(R \mid D) = \dfrac{0.2 \times 0.05}{0.029} = \dfrac{0.01}{0.029} = \dfrac{10}{29}$. Option (b) is the prior; option (d) is $P(Q \mid D)$.`, d: 3, c: 'application', t: [4] }),
  (C) => { C.assert(popCheck(BOLTS, 1000) && bayes(BOLTS, 1).eq(fr(9, 29)), 'Q posterior 9/29'); W(C, ['10/29', '1/5', '1/20', '9/29'], bayes(BOLTS, 2)); });
Q('m20', mk.mcq({ stem: r`In Bayes' theorem $P(E_i \mid A) = \dfrac{P(E_i)\,P(A \mid E_i)}{\sum_j P(E_j)\,P(A \mid E_j)}$, the probability $P(E_i)$ is called the`, opts: ['prior probability of the cause', 'posterior probability of the cause', 'likelihood of the evidence', 'total probability of the evidence'], key: 'a', sol: r`$P(E_i)$ is the **prior**, known before the evidence $A$. $P(E_i \mid A)$ is the posterior, $P(A \mid E_i)$ the likelihood, and the denominator is the total probability of $A$.`, d: 1, c: 'recall', t: [4], time: 40 }),
  (C) => C.key('a'));
Q('m21', mk.mcq({ stem: r`A Kochi forecaster says "rain" on $\dfrac{4}{5}$ of the days that turn out rainy and on $\dfrac{1}{10}$ of the days that stay dry; in the season $\dfrac{3}{10}$ of days are rainy. Given that the forecast says rain, the probability that it actually rains is`, opts: [`$${T('24/31')}$`, `$${T('4/5')}$`, `$${T('31/100')}$`, `$${T('6/25')}$`], key: 'a', sol: r`$P(\text{says rain}) = 0.3 \times 0.8 + 0.7 \times 0.1 = 0.31$, and $P(\text{rain} \mid \text{says rain}) = \dfrac{0.24}{0.31} = \dfrac{24}{31}$. Option (b) is the reverse conditional; option (d) is $P(\text{rain and says rain})$.`, d: 3, c: 'application', t: [4] }),
  (C) => { C.assert(popCheck(RAIN, 100), '100 days'); W(C, ['24/31', '4/5', '31/100', '6/25'], bayes(RAIN, 0)); });
Q('m22', mk.mcq({ stem: r`For a random variable $X$ with $P(X = 0) = \dfrac{1}{4}$, $P(X = 1) = \dfrac{1}{2}$, $P(X = 3) = \dfrac{1}{4}$, recording phone calls missed in an hour, the mean $E(X)$ is`, opts: [`$${T('5/4')}$`, `$${T('4/3')}$`, `$${T('1')}$`, `$${T('3/2')}$`], key: 'a', sol: r`$E(X) = 0 \cdot \dfrac{1}{4} + 1 \cdot \dfrac{1}{2} + 3 \cdot \dfrac{1}{4} = \dfrac{5}{4}$. Option (b) averages the three values without weights.`, d: 1, c: 'understanding', t: [5], time: 50 }),
  (C) => W(C, ['5/4', '4/3', '1', '3/2'], sum(fr(1, 2), fr(3, 4))));
Q('m23', mk.mcq({ stem: r`A stall's daily sales count $X$ has $P(X = x) = k(x^2 + 1)$ for $x = 0, 1, 2, 3$ and $0$ otherwise. The value of $k$ is`, opts: [`$${T('1/18')}$`, `$${T('1/14')}$`, `$${T('1/10')}$`, `$${T('1/4')}$`], key: 'a', sol: r`The probabilities add to $1$: $k(1 + 2 + 5 + 10) = 18k = 1$, so $k = \dfrac{1}{18}$. Option (b) forgets the $+1$ in each term.`, d: 2, c: 'understanding', t: [5] }),
  (C) => W(C, ['1/18', '1/14', '1/10', '1/4'], KDIST.k));
Q('m24', mk.mcq({ stem: r`Two bulbs are taken together from a carton of $6$ at a Jaipur electrical shop, of which $2$ are fused. If $X$ is the number of fused bulbs taken, then $P(X = 1)$ is`, opts: [`$${T('8/15')}$`, `$${T('1/3')}$`, `$${T('2/5')}$`, `$${T('4/9')}$`], key: 'a', sol: r`Of the $\binom{6}{2} = 15$ pairs, $2 \times 4 = 8$ have exactly one fused bulb: $\dfrac{8}{15}$. Option (c) is $P(X = 0)$; option (d) treats the draws as with replacement.`, d: 2, c: 'understanding', t: [5] }),
  (C) => { C.assert(BULBS.p(0).eq(fr(2, 5)), 'P(X=0)'); W(C, ['8/15', '1/3', '2/5', '4/9'], BULBS.p(1)); });

// =============================================================== assertion-reason (6)
Q('ar1', mk.ar({ a: r`In the Dehradun survey, the probability that a chess-club member studies science is $\dfrac{9}{16}$.`, r: r`$P(A \mid B) = \dfrac{n(A \cap B)}{n(B)}$ when all outcomes are equally likely and $n(B) > 0$.`, key: 'a', sol: r`$45$ of the $80$ chess-club members study science: $\dfrac{45}{80} = \dfrac{9}{16}$. R is the counting form of conditional probability used to get A, so R explains A.`, d: 2, c: 'understanding', t: [1] }),
  (C) => { C.assert(pSurvey.sciGivenChess.eq(fr(9, 16)), '9/16'); C.key('a'); });
Q('ar2', mk.ar({ a: r`If $A$ and $B$ are independent events of a factory audit, then $A$ and $B'$ are also independent.`, r: r`$P(A \cap B') = P(A) - P(A \cap B)$ for any two events $A$ and $B$.`, key: 'a', sol: r`By R, $P(A \cap B') = P(A) - P(A)P(B) = P(A)\,P(B')$, which proves A. Both true and R gives the step that explains A.`, d: 3, c: 'analysis', t: [2] }),
  (C) => { const A = (w) => w[0] % 2 === 0, B = (w) => w[0] + w[1] === 7, Bc = (w) => !B(w); C.assert(P(dice2, (w) => A(w) && Bc(w)).eq(P(dice2, A).mul(P(dice2, Bc))), 'A and not-B independent'); C.key('a'); });
Q('ar3', mk.ar({ a: r`When two packets are drawn without replacement from the tea box ($3$ Darjeeling out of $10$), the events "first is Darjeeling" and "second is Darjeeling" are independent.`, r: r`Without replacement, $P(\text{second D} \mid \text{first D}) = \dfrac{2}{9}$, which differs from $P(\text{second D}) = \dfrac{3}{10}$.`, key: 'd', sol: r`R is true: $\dfrac{2}{9} \ne \dfrac{3}{10}$. Because knowing the first draw changes the chance for the second, the events are dependent, so A is false.`, d: 3, c: 'analysis', t: [2] }),
  (C) => { const sp = draws(TEA, 2); C.assert(cond(sp, (w) => w[1] === 'D', (w) => w[0] === 'D').eq(fr(2, 9)) && P(sp, (w) => w[1] === 'D').eq(fr(3, 10)), 'R values'); C.key('d'); });
Q('ar4', mk.ar({ a: r`For the Pune commuter, the posterior probability $P(\text{Route Z} \mid \text{late})$ is larger than the prior $P(\text{Route Z}) = \dfrac{1}{6}$.`, r: r`Route Z has the highest chance of lateness, $\dfrac{1}{4}$, which is more than the overall chance of lateness, $\dfrac{19}{120}$.`, key: 'a', sol: r`$P(Z \mid \text{late}) = \dfrac{5/120}{19/120} = \dfrac{5}{19} > \dfrac{1}{6}$. A posterior rises above its prior exactly when $P(A \mid E_i) > P(A)$, which is what R states, so R explains A.`, d: 4, c: 'evaluation', t: [4] }),
  (C) => { C.assert(bayes(BUS, 2).eq(fr(5, 19)) && bayes(BUS, 2).v > fr(1, 6).v && fr(1, 4).v > total(BUS).v, 'posterior up'); C.key('a'); });
Q('ar5', mk.ar({ a: r`$P(X = x) = \dfrac{x}{6}$ for $x = 1, 2, 3$ defines a probability distribution of a random variable.`, r: r`In any probability distribution, every probability lies between $0$ and $1$.`, key: 'b', sol: r`The values $\dfrac{1}{6}, \dfrac{2}{6}, \dfrac{3}{6}$ are non-negative and add to $1$, so A is true. R is also true, but lying between $0$ and $1$ is not enough on its own; A rests on the sum being $1$, so R does not explain A.`, d: 3, c: 'analysis', t: [5] }),
  (C) => { C.assert(sum(fr(1, 6), fr(2, 6), fr(3, 6)).eq(1), 'sums to 1'); C.key('b'); });
Q('ar6', mk.ar({ a: r`For the number of tosses $X$ when a coin is tossed until a head appears (at most three tosses), $E(X) = \dfrac{7}{4}$.`, r: r`The mean of a random variable is the simple average of its possible values.`, key: 'c', sol: r`$P(X = 1) = \dfrac{1}{2}$, $P(X = 2) = \dfrac{1}{4}$, $P(X = 3) = \dfrac{1}{4}$, so $E(X) = \dfrac{1}{2} + \dfrac{1}{2} + \dfrac{3}{4} = \dfrac{7}{4}$: A is true. R is false: the mean weights each value by its probability; the simple average of $1, 2, 3$ is $2$.`, d: 3, c: 'analysis', t: [5] }),
  (C) => { C.assert(TOSSES.mean.eq(fr(7, 4)), 'mean 7/4'); C.key('c'); });

// =============================================================== true-false (4)
Q('tf1', mk.tf({ stem: r`True or false: in the Dehradun survey, $P(\text{chess} \mid \text{science})$ equals $P(\text{science} \mid \text{chess})$.`, key: 'f', sol: r`False. $P(\text{chess} \mid \text{science}) = \dfrac{45}{120} = \dfrac{3}{8}$ but $P(\text{science} \mid \text{chess}) = \dfrac{45}{80} = \dfrac{9}{16}$: the same overlap is divided by different totals.`, d: 1, c: 'understanding', t: [1] }),
  (C) => { C.assert(!pSurvey.chessGivenSci.eq(pSurvey.sciGivenChess), 'different'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`True or false: if a lab technician's two tests give independent events $A$ and $B$ with $P(A) = 0.3$ and $P(B) = 0.4$, then $P(A' \cap B') = 0.42$.`, key: 't', sol: r`True. $A'$ and $B'$ are also independent: $P(A' \cap B') = 0.7 \times 0.6 = 0.42$.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { C.assert(fr(3, 10).comp().mul(fr(2, 5).comp()).eq(fr(42, 100)), '0.42'); C.key('t'); });
Q('tf3', mk.tf({ stem: r`True or false: in Bayes' theorem the posterior probabilities $P(E_1 \mid A), P(E_2 \mid A), \ldots, P(E_n \mid A)$ of a partition always add up to $1$.`, key: 't', sol: 'True. Given that A has happened, exactly one of the causes in the partition is responsible, so the posteriors add to 1 just as the priors do.', d: 2, c: 'understanding', t: [4] }),
  (C) => { C.assert(sum(...BOLTS.pri.map((_, i) => bayes(BOLTS, i))).eq(1) && sum(...BUS.pri.map((_, i) => bayes(BUS, i))).eq(1), 'posteriors sum to 1'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`True or false: for the absolute difference $X$ of the numbers on two dice, the most likely value of $X$ is $0$.`, key: 'f', sol: r`False. $P(X = 0) = \dfrac{6}{36}$ but $P(X = 1) = \dfrac{10}{36}$, the largest; a difference of $1$ arises in ten ways.`, d: 2, c: 'application', t: [5] }),
  (C) => { const best = DIFF.rows.reduce((a, b) => (b[1].v > a[1].v ? b : a)); C.assert(best[0] === 1 && DIFF.p(1).eq(fr(10, 36)), 'mode 1'); C.key('f'); });

// =============================================================== fill in the blank (4)
Q('fb1', mk.fill({ stem: r`In the Dehradun survey, the probability that a commerce student belongs to the chess club is ____ (as a fraction in lowest terms).`, acc: [['7/16']], sol: r`$35$ of the $80$ commerce students play chess: $\dfrac{35}{80} = \dfrac{7}{16}$.`, d: 1, c: 'understanding', t: [1] }),
  (C) => C.blank(pSurvey.chessGivenCom.v));
Q('fb2', mk.fill({ stem: r`If $A$ and $B$ are independent with $P(A) = \dfrac{1}{4}$ and $P(B) = \dfrac{2}{3}$, as for two independent buses arriving on time, then $P(A \cap B) =$ ____.`, acc: [['1/6']], sol: r`$P(A \cap B) = \dfrac{1}{4} \times \dfrac{2}{3} = \dfrac{1}{6}$.`, d: 1, c: 'understanding', t: [2] }),
  (C) => C.blank(fr(1, 4).mul(fr(2, 3)).v));
Q('fb3', mk.fill({ stem: r`For the Ratnagiri crates, if the mango taken is ripe, the probability that it came from crate I is ____ (as a fraction).`, acc: [['8/13']], sol: r`$P(\text{I} \mid \text{ripe}) = \dfrac{\frac{1}{2} \cdot \frac{8}{12}}{\frac{13}{24}} = \dfrac{8}{13}$.`, d: 2, c: 'understanding', t: [4] }),
  (C) => { C.assert(popCheck(CRATES, 24), '24 mangoes'); C.blank(bayes(CRATES, 0).v); });
Q('fb4', mk.fill({ stem: r`If $X$ counts the girls in a committee of $2$ chosen from $3$ girls and $2$ boys of a Shillong class, then $E(X) =$ ____ (as a decimal).`, acc: [['1.2', '6/5']], sol: r`$P(X = 0) = 0.1$, $P(X = 1) = 0.6$, $P(X = 2) = 0.3$, so $E(X) = 0.6 + 0.6 = 1.2$.`, d: 2, c: 'understanding', t: [5] }),
  (C) => C.blank(GIRLS.mean.v));

// =============================================================== numerical (5)
Q('n01', mk.num({ stem: r`In the Ludhiana bolt factory (P, Q, R make $50\%$, $30\%$, $20\%$; defect rates $2\%$, $3\%$, $5\%$), enter the probability, as a decimal, that a randomly chosen bolt is defective.`, value: 0.029, sol: r`$0.5 \times 0.02 + 0.3 \times 0.03 + 0.2 \times 0.05 = 0.029$.`, scheme: [['0.029', 1]], d: 2, c: 'understanding', t: [3], time: 120 }),
  (C) => C.val(total(BOLTS).v));
Q('n02', mk.num({ stem: r`A Pune quiz contestant knows the answer to a question with probability $0.6$; otherwise she guesses from $5$ options. Enter, as a decimal, the probability that she answers correctly.`, value: 0.68, sol: r`$0.6 \times 1 + 0.4 \times 0.2 = 0.68$.`, scheme: [['0.68', 1]], d: 2, c: 'understanding', t: [3], time: 120 }),
  (C) => { C.assert(popCheck(QUIZ, 25), '25 questions'); C.val(total(QUIZ).v); });
Q('n03', mk.num({ stem: r`For $X$ = the number of girls in a committee of $2$ chosen from $3$ girls and $2$ boys, enter $P(X = 1)$ as a decimal.`, value: 0.6, sol: r`Of the $10$ possible pairs, $3 \times 2 = 6$ contain exactly one girl: $\dfrac{6}{10} = 0.6$.`, scheme: [['0.6', 1]], d: 1, c: 'understanding', t: [5], time: 90 }),
  (C) => C.val(GIRLS.p(1).v));
Q('n04', mk.num({ stem: r`A random variable $X$ for a stall's daily sales has $P(X = x) = k(x^2 + 1)$, $x = 0, 1, 2, 3$. Enter the mean $E(X)$, correct to two decimal places.`, value: 2.33, tol: 0.005, sol: r`$k = \dfrac{1}{18}$; $E(X) = \dfrac{0 \cdot 1 + 1 \cdot 2 + 2 \cdot 5 + 3 \cdot 10}{18} = \dfrac{42}{18} = \dfrac{7}{3} \approx 2.33$.`, scheme: [['2.33', 1]], d: 3, c: 'application', t: [5], time: 150 }),
  (C) => C.val(KDIST.mean.v, 0.005));
Q('n05', mk.num({ stem: r`A rapid test for a cattle disease in an imagined Wayanad district gives a positive result for $90\%$ of sick animals and for $5\%$ of healthy ones; $2\%$ of the herd is sick. Enter, as a decimal, the probability that an animal tests positive.`, value: 0.067, sol: r`$0.02 \times 0.9 + 0.98 \times 0.05 = 0.018 + 0.049 = 0.067$.`, scheme: [['0.067', 1]], d: 2, c: 'understanding', t: [3], time: 120 }),
  (C) => { C.assert(popCheck(TEST, 1000), '1000 animals'); C.val(total(TEST).v); });

// =============================================================== short answer, 2 marks (9)
Q('s201', mk.short({ marks: 2, stem: r`For two events of a Bhopal school's annual-day lucky draw, $P(A) = \dfrac{1}{2}$, $P(B) = \dfrac{1}{3}$ and $P(A \cap B) = \dfrac{1}{4}$. Find $P(A \mid B)$ and $P(B \mid A)$.`, model: r`$P(A \mid B) = \dfrac{1/4}{1/3} = ${T('3/4')}$.\n\n$P(B \mid A) = \dfrac{1/4}{1/2} = ${T('1/2')}$.`, sol: 'Divide the joint probability by the probability of the given event each time.', scheme: [['P(A | B) = 3/4', 1], ['P(B | A) = 1/2', 1]], d: 1, c: 'understanding', t: [1], time: 100 }),
  (C) => { C.assert(fr(1, 4).div(fr(1, 3)).eq(fr(3, 4)) && fr(1, 4).div(fr(1, 2)).eq(fr(1, 2)), 'values'); C.model([T('3/4'), T('1/2')]); });
Q('s202', mk.short({ marks: 2, stem: r`A die is thrown in a classroom game. Given that the number shown is greater than $2$, find the probability that it is a prime number, listing the reduced sample space.`, model: r`Reduced sample space: $\{3, 4, 5, 6\}$, four equally likely outcomes.\n\nPrimes among them: $3$ and $5$, so the probability is $\dfrac{2}{4} = ${T('1/2')}$.`, sol: 'Shrink the sample space to the given event, then count.', scheme: [['Reduced sample space', 1], ['Probability 1/2', 1]], d: 1, c: 'understanding', t: [1], time: 90 }),
  (C) => { C.assert(cond(die, (w) => [2, 3, 5].includes(w[0]), (w) => w[0] > 2).eq(fr(1, 2)), '1/2'); C.model([T('1/2')]); });
Q('s203', mk.short({ marks: 2, stem: r`Two cards are drawn one after the other without replacement from a pack of $52$ for a magic show. Find the probability that both are aces, stating the rule you use.`, model: r`By the multiplication theorem, $P(A_1 \cap A_2) = P(A_1)\,P(A_2 \mid A_1)$.\n\n$= \dfrac{4}{52} \times \dfrac{3}{51} = ${T('1/221')}$.`, sol: 'Second-draw probability is conditional on the first.', scheme: [['Multiplication theorem with conditional second factor', 1], ['1/221', 1]], d: 2, c: 'application', t: [2], time: 100 }),
  (C) => { C.assert(P(draws(cards.map((c) => c.rank === 1), 2), (w) => w[0] && w[1]).eq(fr(1, 221)), 'enumerated'); C.model([T('1/221')]); });
Q('s204', mk.short({ marks: 2, stem: r`Two dice are rolled at a Goa board-game café. Show that the events $A$: "the first die shows an even number" and $B$: "the total is $7$" are independent.`, model: r`$P(A) = \dfrac{1}{2}$, $P(B) = \dfrac{6}{36} = \dfrac{1}{6}$.\n\n$A \cap B = \{(2, 5), (4, 3), (6, 1)\}$, so $P(A \cap B) = \dfrac{3}{36} = ${T('1/12')}$ $= P(A)\,P(B)$. Hence $A$ and $B$ are independent.`, sol: 'Compare P(A ∩ B) with P(A)P(B).', scheme: [['P(A), P(B)', 1], ['P(A ∩ B) = P(A)P(B), conclusion', 1]], d: 2, c: 'application', t: [2], time: 110 }),
  (C) => { const A = (w) => w[0] % 2 === 0, B = (w) => w[0] + w[1] === 7; C.assert(P(dice2, (w) => A(w) && B(w)).eq(P(dice2, A).mul(P(dice2, B))), 'independent'); C.model([T('1/12')]); });
Q('s205', mk.short({ marks: 2, stem: r`At a Surat diamond-cutting unit, two inspectors check a stone independently and miss a flaw with probabilities $\dfrac{1}{4}$ and $\dfrac{1}{5}$. Find the probability that a flawed stone is caught by at least one inspector.`, model: r`Both miss with probability $\dfrac{1}{4} \times \dfrac{1}{5} = \dfrac{1}{20}$ (independence).\n\nCaught by at least one: $1 - \dfrac{1}{20} = ${T('19/20')}$.`, sol: 'Use the complement of "both miss".', scheme: [['Both miss 1/20', 1], ['19/20', 1]], d: 2, c: 'application', t: [2], time: 100 }),
  (C) => { const sp = cart(range(1, 4), range(1, 5)); C.assert(P(sp, ([a, b]) => a > 1 || b > 1).eq(fr(19, 20)), 'enumerated'); C.model([T('19/20')]); });
Q('s206', mk.short({ marks: 2, stem: r`For the Kochi forecaster (rainy days $\dfrac{3}{10}$ of the season; says "rain" on $\dfrac{4}{5}$ of rainy days and $\dfrac{1}{10}$ of dry days), find the probability that the forecast on a given day is "rain".`, model: r`By total probability, $P(\text{says rain}) = \dfrac{3}{10} \cdot \dfrac{4}{5} + \dfrac{7}{10} \cdot \dfrac{1}{10}$\n\n$= \dfrac{24}{100} + \dfrac{7}{100} = ${T('31/100')}$.`, sol: 'Two cases: rainy and dry days.', scheme: [['Total probability set-up', 1], ['31/100', 1]], d: 2, c: 'application', t: [3], time: 110 }),
  (C) => { C.assert(popCheck(RAIN, 100), 'population'); C.model([T('31/100')]); });
Q('s207', mk.short({ marks: 2, stem: r`At the Ratnagiri packhouse, one mango is moved unseen from crate I ($8$ ripe, $4$ raw) to crate II ($5$ ripe, $7$ raw), and then a mango is taken from crate II. Find the probability that it is ripe.`, model: r`If the moved mango is ripe (probability $\dfrac{8}{12}$), crate II has $6$ ripe of $13$; if raw ($\dfrac{4}{12}$), it has $5$ ripe of $13$.\n\n$P = \dfrac{8}{12} \cdot \dfrac{6}{13} + \dfrac{4}{12} \cdot \dfrac{5}{13} = \dfrac{68}{156} = ${T('17/39')}$.`, sol: 'Condition on the colour of the moved mango.', scheme: [['Two cases with their probabilities', 1], ['17/39', 1]], d: 3, c: 'analysis', t: [3], time: 130 }),
  (C) => { const c1 = bag({ R: 8, U: 4 }), c2 = bag({ R: 5, U: 7 }); const sp = cart(c1, [...c2, 'MOVED']); C.assert(P(sp, ([m, x]) => (x === 'MOVED' ? m === 'R' : x === 'R')).eq(fr(17, 39)), 'enumerated'); C.model([T('17/39')]); });
Q('s208', mk.short({ marks: 2, stem: r`Check whether $P(X = x) = \dfrac{x - 1}{6}$ for $x = 1, 2, 3, 4$ can be the probability distribution of the number of misprints on a page.`, model: r`Values: $P(X = 1) = 0$, $P(X = 2) = \dfrac{1}{6}$, $P(X = 3) = \dfrac{2}{6}$, $P(X = 4) = \dfrac{3}{6}$: all lie between $0$ and $1$.\n\nSum $= \dfrac{0 + 1 + 2 + 3}{6} = 1$, so it **is** a probability distribution.`, sol: 'Check non-negativity and that the sum is 1.', scheme: [['Each value in [0, 1]', 1], ['Sum is 1, conclusion', 1]], d: 2, c: 'application', t: [5], time: 100 }),
  (C) => { const ps = [1, 2, 3, 4].map((x) => fr(x - 1, 6)); C.assert(ps.every((p) => p.v >= 0 && p.v <= 1) && sum(...ps).eq(1), 'valid'); C.model([0, 1]); });
Q('s209', mk.short({ marks: 2, stem: r`A coin is tossed until a head appears or until it has been tossed three times, at a Mysuru fair stall. Write the probability distribution of the number of tosses $X$.`, model: r`$X = 1$: head first, $P = ${T('1/2')}$.\n\n$X = 2$: $TH$, $P = ${T('1/4')}$. $X = 3$: $TT$ followed by anything, $P = ${T('1/4')}$. (Check: the probabilities add to $1$.)`, sol: 'The third toss is made whatever happens after two tails.', scheme: [['P(X = 1), P(X = 2)', 1], ['P(X = 3) and check', 1]], d: 2, c: 'application', t: [5], time: 100 }),
  (C) => { C.assert(TOSSES.p(1).eq(fr(1, 2)) && TOSSES.p(2).eq(fr(1, 4)) && TOSSES.p(3).eq(fr(1, 4)), 'distribution'); C.model([T('1/2'), T('1/4')]); });

// =============================================================== short answer, 3 marks (10)
Q('s301', mk.short({ marks: 3, stem: r`In the Dehradun survey of $200$ Class 12 students ($120$ science, of whom $45$ are in the chess club; $80$ commerce, of whom $35$ are in the chess club), find (i) $P(\text{science} \mid \text{chess})$, (ii) $P(\text{chess} \mid \text{commerce})$, and (iii) decide whether "commerce" and "chess" are independent.`, model: r`(i) Chess-club members: $45 + 35 = 80$; $P(\text{science} \mid \text{chess}) = \dfrac{45}{80} = ${T('9/16')}$.\n\n(ii) $P(\text{chess} \mid \text{commerce}) = \dfrac{35}{80} = ${T('7/16')}$.\n\n(iii) $P(\text{chess}) = \dfrac{80}{200} = ${T('2/5')}$, which differs from $${T('7/16')}$, so the events are **not** independent.`, sol: 'Use the table counts for each conditional probability.', scheme: [['(i) 9/16', 1], ['(ii) 7/16', 1], ['(iii) comparison and conclusion', 1]], d: 2, c: 'application', t: [1, 2], time: 200 }),
  (C) => { C.assert(pSurvey.sciGivenChess.eq(fr(9, 16)) && pSurvey.chessGivenCom.eq(fr(7, 16)) && !pSurvey.chessGivenCom.eq(pSurvey.chess), 'survey'); C.model([T('9/16'), T('7/16'), T('2/5')]); });
Q('s302', mk.short({ marks: 3, stem: r`For two events of an online-shopping survey, $P(A) = 0.5$, $P(B) = 0.4$ and $P(A \mid B) = 0.6$. Find $P(A \cap B)$, $P(A \cup B)$ and $P(B \mid A)$.`, model: r`$P(A \cap B) = P(B)\,P(A \mid B) = 0.4 \times 0.6 = 0.24$.\n\n$P(A \cup B) = 0.5 + 0.4 - 0.24 = 0.66$.\n\n$P(B \mid A) = \dfrac{0.24}{0.5} = 0.48$.`, sol: 'Multiplication theorem first, then the addition theorem.', scheme: [['P(A ∩ B) = 0.24', 1], ['P(A ∪ B) = 0.66', 1], ['P(B | A) = 0.48', 1]], d: 2, c: 'application', t: [1], time: 180 }),
  (C) => { const AB = fr(2, 5).mul(fr(3, 5)); C.assert(AB.eq(fr(24, 100)) && fr(1, 2).add(fr(2, 5)).sub(AB).eq(fr(66, 100)) && AB.div(fr(1, 2)).eq(fr(48, 100)), 'values'); C.model([0.24, 0.66, 0.48]); });
Q('s303', mk.short({ marks: 3, stem: r`From the Siliguri box of $10$ tea packets ($3$ Darjeeling, $7$ Assam), three packets are taken one by one without replacement. Find the probability that (i) all three are Assam, (ii) exactly one is Darjeeling.`, model: r`(i) $\dfrac{7}{10} \cdot \dfrac{6}{9} \cdot \dfrac{5}{8} = ${T('7/24')}$.\n\n(ii) The Darjeeling packet can come first, second or third; each order has probability $\dfrac{3 \cdot 7 \cdot 6}{10 \cdot 9 \cdot 8} = \dfrac{7}{40}$, so $P = 3 \times \dfrac{7}{40} = ${T('21/40')}$.`, sol: 'Multiplication theorem along each order of draws.', scheme: [['(i) product of conditional probabilities', 1], ['(i) 7/24', 1], ['(ii) three orders, 21/40', 1]], d: 3, c: 'application', t: [2], time: 200 }),
  (C) => { const sp = draws(TEA, 3); C.assert(P(sp, (w) => w.every((x) => x === 'A')).eq(fr(7, 24)) && P(sp, (w) => w.filter((x) => x === 'D').length === 1).eq(fr(21, 40)), 'enumerated'); C.model([T('7/24'), T('21/40')]); });
Q('s304', mk.short({ marks: 3, stem: r`Ayesha and Kabir at the Lucknow badminton camp serve independently, with good-serve probabilities $\dfrac{4}{5}$ and $\dfrac{2}{3}$. Each serves once. Find the probability that (i) both serves are good, (ii) at least one is good, (iii) only Kabir's is good.`, model: r`(i) $\dfrac{4}{5} \cdot \dfrac{2}{3} = ${T('8/15')}$.\n\n(ii) $1 - \dfrac{1}{5} \cdot \dfrac{1}{3} = ${T('14/15')}$.\n\n(iii) $\dfrac{1}{5} \cdot \dfrac{2}{3} = ${T('2/15')}$.`, sol: 'Independence lets us multiply; use the complement for "at least one".', scheme: [['(i) 8/15', 1], ['(ii) 14/15', 1], ['(iii) 2/15', 1]], d: 2, c: 'application', t: [2], time: 180 }),
  (C) => { const sp = cart(range(1, 5), range(1, 3)); const A = ([a]) => a <= 4, K = ([, b]) => b <= 2; C.assert(P(sp, (w) => A(w) && K(w)).eq(fr(8, 15)) && P(sp, (w) => A(w) || K(w)).eq(fr(14, 15)) && P(sp, (w) => !A(w) && K(w)).eq(fr(2, 15)), 'enumerated'); C.model([T('8/15'), T('14/15'), T('2/15')]); });
Q('s305', mk.short({ marks: 3, stem: r`The Pune commuter (routes X, Y, Z with probabilities $\dfrac{1}{2}$, $\dfrac{1}{3}$, $\dfrac{1}{6}$; late with probabilities $\dfrac{1}{10}$, $\dfrac{1}{5}$, $\dfrac{1}{4}$) reaches office late one morning. Find the probability that she took route Y.`, model: r`$P(\text{late}) = \dfrac{1}{20} + \dfrac{1}{15} + \dfrac{1}{24} = \dfrac{6 + 8 + 5}{120} = \dfrac{19}{120}$.\n\nBy Bayes' theorem, $P(Y \mid \text{late}) = \dfrac{\frac{1}{3} \cdot \frac{1}{5}}{\frac{19}{120}} = \dfrac{8/120}{19/120} = ${T('8/19')}$.`, sol: 'Total probability in the denominator, the Y term on top.', scheme: [['Total probability 19/120', 1], ['Bayes set-up', 1], ['8/19', 1]], d: 3, c: 'application', t: [3, 4], time: 220 }),
  (C) => { C.assert(popCheck(BUS, 120), 'population'); C.assert(bayes(BUS, 1).eq(fr(8, 19)), '8/19'); C.model([T('8/19')]); });
Q('s306', mk.short({ marks: 3, stem: r`For the Wayanad cattle test ($2\%$ of animals sick; positive for $90\%$ of sick and $5\%$ of healthy animals), an animal tests positive. Find the probability that it is actually sick, and comment on the answer.`, model: r`$P(+) = 0.02 \times 0.9 + 0.98 \times 0.05 = 0.067$.\n\n$P(\text{sick} \mid +) = \dfrac{0.018}{0.067} = ${T('18/67')}$, about $0.27$.\n\nComment: although the test is good, most positives come from the large healthy group, so a positive result alone is weak evidence; a second test is advisable.`, sol: 'Bayes with a rare condition.', scheme: [['P(+) = 0.067', 1], ['18/67', 1], ['Sensible comment', 1]], d: 4, c: 'evaluation', t: [4], time: 220 }),
  (C) => { C.assert(popCheck(TEST, 1000) && bayes(TEST, 0).eq(fr(18, 67)), 'posterior'); C.model([T('18/67'), 0.067]); });
Q('s307', mk.short({ marks: 3, stem: r`The Pune quiz contestant knows an answer with probability $\dfrac{3}{5}$ and otherwise guesses from $5$ options. Given that she answered a question correctly, find the probability that she actually knew it.`, model: r`$P(\text{correct}) = \dfrac{3}{5} \cdot 1 + \dfrac{2}{5} \cdot \dfrac{1}{5} = \dfrac{17}{25}$.\n\n$P(\text{knew} \mid \text{correct}) = \dfrac{3/5}{17/25} = ${T('15/17')}$.`, sol: 'Two causes of a correct answer: knowing and lucky guessing.', scheme: [['Two cases with probabilities', 1], ['P(correct) = 17/25', 1], ['15/17', 1]], d: 3, c: 'application', t: [4], time: 200 }),
  (C) => { C.assert(popCheck(QUIZ, 25) && bayes(QUIZ, 0).eq(fr(15, 17)), 'posterior'); C.model([T('15/17'), T('17/25')]); });
Q('s308', mk.short({ marks: 3, stem: r`Two bulbs are taken together from the Jaipur carton of $6$ ($2$ fused). Find the probability distribution of the number $X$ of fused bulbs and its mean.`, model: r`$P(X = 0) = \dfrac{\binom{4}{2}}{\binom{6}{2}} = ${T('2/5')}$, $P(X = 1) = \dfrac{2 \cdot 4}{15} = ${T('8/15')}$, $P(X = 2) = \dfrac{1}{15}$.\n\n$E(X) = 0 + \dfrac{8}{15} + \dfrac{2}{15} = ${T('2/3')}$.`, sol: 'Count pairs; the probabilities must add to 1.', scheme: [['P(X = 0) and P(X = 1)', 1], ['P(X = 2)', 1], ['Mean 2/3', 1]], d: 3, c: 'application', t: [5], time: 200 }),
  (C) => { C.assert(BULBS.p(2).eq(fr(1, 15)) && BULBS.mean.eq(fr(2, 3)), 'distribution'); C.model([T('2/5'), T('8/15'), T('2/3')]); });
Q('s309', mk.short({ marks: 3, stem: r`For a stall's daily sales $X$ with $P(X = x) = k(x^2 + 1)$, $x = 0, 1, 2, 3$, find $k$, $P(X \ge 2)$ and $E(X)$.`, model: r`$k(1 + 2 + 5 + 10) = 1$, so $k = ${T('1/18')}$.\n\n$P(X \ge 2) = \dfrac{5 + 10}{18} = ${T('5/6')}$.\n\n$E(X) = \dfrac{0 + 2 + 10 + 30}{18} = ${T('7/3')}$.`, sol: 'Normalise first, then add and weight.', scheme: [['k = 1/18', 1], ['P(X ≥ 2) = 5/6', 1], ['E(X) = 7/3', 1]], d: 3, c: 'application', t: [5], time: 200 }),
  (C) => { C.assert(sum(...KDIST.rows.filter(([x]) => x >= 2).map(([, p]) => p)).eq(fr(5, 6)), 'tail'); C.model([T('1/18'), T('5/6'), T('7/3')]); });
Q('s310', mk.short({ marks: 3, stem: r`Two dice are thrown at a Kolkata maths-club stall and $X$ is the absolute difference of the numbers shown. Find $P(X = 0)$, $P(X = 3)$ and $P(X \le 1)$.`, model: r`$X = 0$: the six doubles, $P = ${T('1/6')}$.\n\n$X = 3$: $(1, 4), (2, 5), (3, 6)$ and reverses, $6$ outcomes, $P = ${T('1/6')}$.\n\n$X \le 1$: $6 + 10 = 16$ outcomes, $P = ${T('4/9')}$.`, sol: 'Count the 36 outcomes by difference.', scheme: [['P(X = 0)', 1], ['P(X = 3)', 1], ['P(X ≤ 1) = 4/9', 1]], d: 2, c: 'application', t: [5], time: 180 }),
  (C) => { C.assert(DIFF.p(0).eq(fr(1, 6)) && DIFF.p(3).eq(fr(1, 6)) && DIFF.p(0).add(DIFF.p(1)).eq(fr(4, 9)), 'counts'); C.model([T('1/6'), T('4/9')]); });

// =============================================================== long answer, 5 marks (6)
Q('l01', mk.long({ stem: r`The Ludhiana bolt factory has machines P, Q and R making $50\%$, $30\%$ and $20\%$ of its bolts, with $2\%$, $3\%$ and $5\%$ of their output defective.\n\n(a) Find the probability that a bolt chosen at random is defective. [2]\n\n(b) A bolt chosen at random is defective. Find the probability that it was made by each machine, and say which machine is most likely responsible. [3]`, model: r`**(a)** $P(D) = 0.5 \times 0.02 + 0.3 \times 0.03 + 0.2 \times 0.05 = 0.01 + 0.009 + 0.01 = 0.029$.\n\n**(b)** By Bayes' theorem: $P(P \mid D) = \dfrac{0.01}{0.029} = ${T('10/29')}$, $P(Q \mid D) = \dfrac{0.009}{0.029} = ${T('9/29')}$, $P(R \mid D) = \dfrac{0.01}{0.029} = ${T('10/29')}$.\n\nMachines P and R are equally likely, and Q is slightly less likely; the three posteriors add to $1$.`, sol: 'Total probability, then Bayes for each machine.', scheme: [['(a) set-up', 1], ['(a) 0.029', 1], ['(b) Bayes formula', 1], ['(b) 10/29, 9/29, 10/29', 1], ['(b) conclusion', 1]], d: 3, c: 'application', t: [3, 4], time: 480 }),
  (C) => { C.assert(popCheck(BOLTS, 1000), 'population'); C.assert(bayes(BOLTS, 0).eq(fr(10, 29)) && bayes(BOLTS, 1).eq(fr(9, 29)) && bayes(BOLTS, 2).eq(fr(10, 29)), 'posteriors'); C.model([0.029, T('10/29'), T('9/29')]); });
Q('l02', mk.long({ stem: r`The Wayanad cattle test gives a positive result for $90\%$ of sick animals and for $5\%$ of healthy animals; $2\%$ of the herd is sick.\n\n(a) Find the probability that an animal tests positive. [2]\n\n(b) An animal tests positive. Find the probability that it is sick. [2]\n\n(c) Should the herd owner treat every positive animal as sick? Give a reason. [1]`, model: r`**(a)** $P(+) = 0.02 \times 0.9 + 0.98 \times 0.05 = 0.018 + 0.049 = 0.067$.\n\n**(b)** $P(\text{sick} \mid +) = \dfrac{0.018}{0.067} = ${T('18/67')}$, about $0.27$.\n\n**(c)** No: about three out of four positive animals are actually healthy, because healthy animals vastly outnumber sick ones. A confirmatory test is needed before treatment.`, sol: 'A rare condition makes the posterior small.', scheme: [['(a) set-up', 1], ['(a) 0.067', 1], ['(b) Bayes', 1], ['(b) 18/67', 1], ['(c) reasoned judgement', 1]], d: 4, c: 'evaluation', t: [3, 4], time: 480 }),
  (C) => { C.assert(popCheck(TEST, 1000), 'population'); C.assert(fr(1).sub(bayes(TEST, 0)).v > 0.7, 'about three in four positives healthy'); C.model([0.067, T('18/67')]); });
Q('l03', mk.long({ stem: r`At the Ratnagiri packhouse, crate I holds $8$ ripe and $4$ raw mangoes and crate II holds $5$ ripe and $7$ raw.\n\n(a) A coin decides the crate and one mango is taken. Find the probability that it is ripe. [2]\n\n(b) The mango taken is ripe. Find the probability that it came from crate II. [1]\n\n(c) Instead, one mango is moved unseen from crate I to crate II and a mango is then taken from crate II. Find the probability that it is ripe. [2]`, model: r`**(a)** $P(\text{ripe}) = \dfrac{1}{2} \cdot \dfrac{8}{12} + \dfrac{1}{2} \cdot \dfrac{5}{12} = ${T('13/24')}$.\n\n**(b)** $P(\text{II} \mid \text{ripe}) = \dfrac{\frac{1}{2} \cdot \frac{5}{12}}{\frac{13}{24}} = ${T('5/13')}$.\n\n**(c)** Moved mango ripe ($\dfrac{2}{3}$): crate II has $6$ ripe of $13$; raw ($\dfrac{1}{3}$): $5$ ripe of $13$. $P = \dfrac{2}{3} \cdot \dfrac{6}{13} + \dfrac{1}{3} \cdot \dfrac{5}{13} = ${T('17/39')}$.`, sol: 'Total probability twice, with Bayes in between.', scheme: [['(a) set-up', 1], ['(a) 13/24', 1], ['(b) 5/13', 1], ['(c) two cases', 1], ['(c) 17/39', 1]], d: 3, c: 'application', t: [3, 4], time: 480 }),
  (C) => { C.assert(popCheck(CRATES, 24) && bayes(CRATES, 1).eq(fr(5, 13)), 'crate posterior'); C.assert(fr(2, 3).mul(fr(6, 13)).add(fr(1, 3).mul(fr(5, 13))).eq(fr(17, 39)), 'transfer'); C.model([T('13/24'), T('5/13'), T('17/39')]); });
Q('l04', mk.long({ stem: r`Two bulbs are taken together from a carton of $6$ bulbs at a Jaipur shop, of which $2$ are fused; $X$ is the number of fused bulbs taken.\n\n(a) Find the probability distribution of $X$ and check that it is a valid distribution. [3]\n\n(b) Find the mean of $X$ and interpret it for the shopkeeper. [2]`, model: r`**(a)** There are $\binom{6}{2} = 15$ equally likely pairs.\n\n$P(X = 0) = \dfrac{6}{15} = ${T('2/5')}$, $P(X = 1) = \dfrac{8}{15}$, $P(X = 2) = \dfrac{1}{15}$. Each lies in $[0, 1]$ and they add to $\dfrac{15}{15} = 1$.\n\n**(b)** $E(X) = 0 \cdot \dfrac{6}{15} + 1 \cdot \dfrac{8}{15} + 2 \cdot \dfrac{1}{15} = ${T('2/3')}$.\n\nOver many such pairs, the shopkeeper hands out on average two fused bulbs in every three pairs.`, sol: 'Count pairs, check the total, then weight the values.', scheme: [['(a) P(X = 0)', 1], ['(a) P(X = 1), P(X = 2)', 1], ['(a) validity check', 1], ['(b) mean 2/3', 1], ['(b) interpretation', 1]], d: 3, c: 'application', t: [5], time: 480 }),
  (C) => { C.assert(BULBS.p(1).eq(fr(8, 15)) && BULBS.mean.eq(fr(2, 3)), 'distribution'); C.model([T('2/5'), T('2/3'), 15]); });
Q('l05', mk.long({ stem: r`At a Kolkata maths-club stall two dice are thrown and $X$ is the absolute difference of the numbers shown.\n\n(a) Write the probability distribution of $X$. [3]\n\n(b) Find $E(X)$. [1]\n\n(c) The stall pays ₹$10$ when the difference is $4$ or more and nothing otherwise. Find the probability of a payout. [1]`, model: r`**(a)** Counting the $36$ outcomes:\n\n$P(X = 0) = \dfrac{6}{36}$, $P(X = 1) = \dfrac{10}{36}$, $P(X = 2) = \dfrac{8}{36}$, $P(X = 3) = \dfrac{6}{36}$, $P(X = 4) = \dfrac{4}{36}$, $P(X = 5) = \dfrac{2}{36}$.\n\n**(b)** $E(X) = \dfrac{0 + 10 + 16 + 18 + 16 + 10}{36} = \dfrac{70}{36} = ${T('35/18')}$.\n\n**(c)** $P(X \ge 4) = \dfrac{4 + 2}{36} = ${T('1/6')}$.`, sol: 'Tabulate the 36 outcomes by difference.', scheme: [['(a) values 0 to 2', 1], ['(a) values 3 to 5', 1], ['(a) total 1', 1], ['(b) 35/18', 1], ['(c) 1/6', 1]], d: 3, c: 'application', t: [5], time: 480 }),
  (C) => { C.assert(DIFF.mean.eq(fr(35, 18)) && DIFF.p(4).add(DIFF.p(5)).eq(fr(1, 6)) && DIFF.rows.length === 6, 'distribution'); C.model([T('35/18'), T('1/6'), 70]); });
Q('l06', mk.long({ stem: r`A Pune commuter chooses route X, Y or Z with probabilities $\dfrac{1}{2}$, $\dfrac{1}{3}$, $\dfrac{1}{6}$; she is late with probabilities $\dfrac{1}{10}$, $\dfrac{1}{5}$, $\dfrac{1}{4}$ on these routes.\n\n(a) Find the probability that she is late on a given day. [2]\n\n(b) She was late today. Find the posterior probability of each route. [2]\n\n(c) Which route's probability increased most compared with its prior, and why? [1]`, model: r`**(a)** $P(L) = \dfrac{6}{120} + \dfrac{8}{120} + \dfrac{5}{120} = ${T('19/120')}$.\n\n**(b)** $P(X \mid L) = ${T('6/19')}$, $P(Y \mid L) = ${T('8/19')}$, $P(Z \mid L) = ${T('5/19')}$; they add to $1$.\n\n**(c)** Compare with the priors $\dfrac{1}{2}$, $\dfrac{1}{3}$, $\dfrac{1}{6}$: X falls, while Y and Z rise. Z rises most in relative terms (from $\dfrac{1}{6}$ to $\dfrac{5}{19}$, about $1.6$ times) because its lateness rate $\dfrac{1}{4}$ is the highest.`, sol: 'Posterior = prior × likelihood ÷ total.', scheme: [['(a) 19/120', 1], ['(a) correct terms', 1], ['(b) three posteriors', 1], ['(b) check', 1], ['(c) comparison with reason', 1]], d: 4, c: 'analysis', t: [3, 4], time: 480 }),
  (C) => { C.assert(popCheck(BUS, 120), 'population'); const post = [0, 1, 2].map((i) => bayes(BUS, i)); C.assert(post[0].eq(fr(6, 19)) && post[1].eq(fr(8, 19)) && post[2].eq(fr(5, 19)), 'posteriors'); const ratio = post.map((p, i) => p.div(BUS.pri[i]).v); C.assert(ratio[2] > ratio[1] && ratio[1] > ratio[0], 'Z rises most'); C.model([T('19/120'), T('6/19'), T('8/19'), T('5/19')]); });
